t = int(input())
for _ in range(t):
	n = int(input())
	a = list(map(int, input().split()))
	a.sort()
	greater = a[n // 2:]
	lesser = a[:n // 2]
	valid = []
	for i in range(n // 2):
		valid.append(greater[i])
		valid.append(lesser[i])
	if n % 2 == 1:
		valid.append(greater[-1])
	interest = True
	for i in range(1, n - 1):
		if not (valid[i - 1] < valid[i] > valid[i + 1] or valid[i - 1] > valid[i] < valid[i + 1]):
			interest = False
	if interest == True:
		print(*valid)
	else:
		print(-1)
